import * as T from './vendor/three.module.js';
import {buildCopier,poseParts,explosionAt} from './model.js';
const $=id=>document.getElementById(id), stage=$('stage'), section=$('experience'), range=$('progress');
let renderer,scene,camera,copier,shadow,ground,p=0,target=0,last=0,visible=true,yaw=0,yawTarget=0,pitch=0,pitchTarget=0,chapter=-1;
const mq=matchMedia('(prefers-reduced-motion: reduce)');let reduced=mq.matches;
function motionUI(){$('motion').textContent='Motion: '+(reduced?'reduced':'full');$('motion').setAttribute('aria-pressed',String(reduced));}
function readScroll(){target=T.MathUtils.clamp((scrollY-section.offsetTop)/(section.offsetHeight-innerHeight),0,1)}
const chapters=[['Photocopier Machines.<br>Sales, Parts & Service.','Discover premium Xerox, Canon & digital copiers with trusted support from Sandeep Das at COPYSTAR International.','COMPLETE COPIER MACHINES','Heavy-duty multifunction printers for commercial & office printing.','STAGE 01 · ASSEMBLED MACHINE',['Xerox & Canon Copiers','Heavy-Duty Print & Scan','Sales & AMC by Sandeep Das']],['Genuine Spare Parts.<br>Toner & Drive Gears.','From toner cartridges and drums to fuser rollers and gears, explore the parts that keep every machine printing.','PARTS & CONSUMABLES','Toners, drums, fuser rollers & precision gears.','STAGE 02 · EXPLODED PARTS VIEW',['CMYK & Black Toners','Rollers, Drums & Gears','Verified Compatible Fit']],['Expert Repair & AMC.<br>Ready for Work.','Fast diagnosis, certified technician service and bulk delivery across Nepal. Complete print solutions ready for you.','REPAIR & AMC SUPPORT','Trusted maintenance and bulk delivery by Sandeep Das & team.','STAGE 03 · REASSEMBLED & READY',['On-site Diagnostics','Preventive Maintenance','Pan-Nepal Delivery']]];
function ui(){let n=p<.25?0:p<.66?1:2;if(n!==chapter){chapter=n;$('chapter-title').innerHTML=chapters[n][0];$('chapter-copy').textContent=chapters[n][1];$('chapter-number').textContent='0'+(n+1);$('detail-label').textContent=chapters[n][2];$('detail-copy').textContent=chapters[n][3];const pill=$('stage-pill');if(pill)pill.textContent=chapters[n][4];const tags=$('stage-tags');if(tags&&chapters[n][5])tags.innerHTML=chapters[n][5].map(t=>`<span>${t}</span>`).join('');document.querySelectorAll('[data-progress]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)))}range.value=Math.round(p*1000);const pc=Math.round(p*100);$('percent').textContent=String(pc).padStart(2,'0')+'%';const state=p<.08?'Assembled':p<.43?'Separating':p<.61?'Exploded view':p<.94?'Reassembling':'Complete';range.setAttribute('aria-valuetext',state+', '+pc+' percent');$('state-caption').textContent=reduced?'Reduced motion / assembled view':state+' / '+(p<.08?'ready to explore':pc+'% explored');$('annotations').style.opacity=!reduced&&explosionAt(p)>.9?'1':'0';}
function screenTexture(){const c=document.createElement('canvas');c.width=512;c.height=320;const x=c.getContext('2d');x.fillStyle='#10252c';x.fillRect(0,0,512,320);x.fillStyle='#f3f8f5';x.font='500 28px Arial';x.fillText('Ready to print',26,47);x.fillStyle='#718d93';x.font='16px Arial';x.fillText('COPYSTAR · SANDEEP DAS',26,76);['Copy','Scan','Print'].forEach((s,i)=>{x.fillStyle=['#df252e','#2e807d','#506b7c'][i];x.fillRect(26+i*158,110,144,137);x.fillStyle='white';x.strokeStyle='white';x.lineWidth=3;x.strokeRect(72+i*158,134,41,49);x.fillRect(81+i*158,146,25,3);x.fillRect(81+i*158,156,25,3);x.font='20px Arial';x.fillText(s,73+i*158,223)});x.fillStyle='#8eb8b9';x.font='15px Arial';x.fillText('●  System ready',26,292);const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;return tx}
function setup(){renderer=new T.WebGLRenderer({canvas:$('scene'),antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;scene=new T.Scene();camera=new T.PerspectiveCamera(34,1,.1,100);scene.add(new T.HemisphereLight(0xf4f8ff,0x8e9987,3));const key=new T.DirectionalLight(0xfffcf2,4.3);key.position.set(-4,9,7);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-6,right:6,top:8,bottom:-5,near:.1,far:25});key.shadow.bias=-.0004;key.shadow.normalBias=.035;key.shadow.radius=3;scene.add(key);const rim=new T.DirectionalLight(0xffffff,2.5);rim.position.set(5,5,-4);scene.add(rim);const fill=new T.DirectionalLight(0xa9c8ff,.8);fill.position.set(0,3,6);scene.add(fill);ground=new T.Mesh(new T.PlaneGeometry(200,200),new T.ShadowMaterial({opacity:.12}));ground.rotation.x=-Math.PI/2;ground.position.y=.14;ground.receiveShadow=true;scene.add(ground);
// A soft contact shadow supports the machine without a hard platform.
const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(64,64,4,64,64,64);g.addColorStop(0,'rgba(34,48,36,.22)');g.addColorStop(.5,'rgba(34,48,36,.11)');g.addColorStop(1,'rgba(34,48,36,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);shadow=new T.Mesh(new T.PlaneGeometry(5.8,4.8),new T.MeshBasicMaterial({map:new T.CanvasTexture(c),transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.151;scene.add(shadow);copier=buildCopier(screenTexture());scene.add(copier.root);resize();$('loader').hidden=true;readScroll();motionUI();initRotateControls();requestAnimationFrame(frame)}
function resize(){if(!renderer)return;const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();positionCamera()}
function positionCamera(){if(!camera)return;const e=reduced?0:explosionAt(p),height=5.9+2.1*e,width=5.8+3.4*e;const dist=Math.max(height,width/camera.aspect)/(2*Math.tan(T.MathUtils.degToRad(camera.fov/2)));const angle=.52+yaw;camera.position.set(Math.sin(angle)*dist,2.25+e*.55+dist*(.32+pitch),Math.cos(angle)*dist);camera.lookAt(0,2.25+e*.55,0)}
let isDragging=false,isDraggingPart=false,activePart=null,startX=0,startY=0,startYaw=0,startPitch=0,autoSpin=false;
const raycaster=new T.Raycaster();
const pointerVec=new T.Vector2();
const dragPlane=new T.Plane();
const planeIntersect=new T.Vector3();
const dragOffset=new T.Vector3();
function updateAutoSpinUI(){const b=$('btn-rot-auto');if(b){b.setAttribute('aria-pressed',String(autoSpin));b.classList.toggle('active',autoSpin);}}
function updatePartLabel(cx,cy){const pl=$('part-label');if(!pl)return;const r=stage.getBoundingClientRect();const x=Math.max(10,Math.min(r.width-130,cx-r.left+14));const y=Math.max(10,Math.min(r.height-36,cy-r.top-26));pl.style.left=x+'px';pl.style.top=y+'px';}
function getIntersectedPart(cx,cy){if(!copier||!copier.root||!camera)return null;const rect=renderer.domElement.getBoundingClientRect();if(!rect.width||!rect.height)return null;pointerVec.x=((cx-rect.left)/rect.width)*2-1;pointerVec.y=-((cy-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointerVec,camera);const hits=raycaster.intersectObjects(copier.root.children,true);if(!hits.length)return null;let obj=hits[0].object;while(obj&&obj!==copier.root){const found=copier.parts.find(p=>p.g===obj);if(found)return {part:found,point:hits[0].point};obj=obj.parent;}return null;}
function initRotateControls(){const s=$('stage');if(!s)return;s.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType==='mouse')return;if(e.target.closest('button,a'))return;const hit=getIntersectedPart(e.clientX,e.clientY);if(hit){isDraggingPart=true;activePart=hit.part;if(!activePart.userOffset)activePart.userOffset=new T.Vector3(0,0,0);const camDir=new T.Vector3();camera.getWorldDirection(camDir);dragPlane.setFromNormalAndCoplanarPoint(camDir.negate(),activePart.g.position);if(raycaster.ray.intersectPlane(dragPlane,planeIntersect)){dragOffset.copy(planeIntersect).sub(activePart.g.position);}else{dragOffset.set(0,0,0);}s.classList.add('is-dragging-part');const pl=$('part-label'),pn=$('part-name');if(pl&&pn){pn.textContent=activePart.g.name||'Part';pl.hidden=false;updatePartLabel(e.clientX,e.clientY);}autoSpin=false;updateAutoSpinUI();try{s.setPointerCapture(e.pointerId)}catch(_){}return;}isDragging=true;startX=e.clientX;startY=e.clientY;startYaw=yawTarget;startPitch=pitchTarget;autoSpin=false;updateAutoSpinUI();s.classList.add('is-dragging');try{s.setPointerCapture(e.pointerId)}catch(_){}});s.addEventListener('pointermove',e=>{if(isDraggingPart&&activePart){const rect=renderer.domElement.getBoundingClientRect();pointerVec.x=((e.clientX-rect.left)/rect.width)*2-1;pointerVec.y=-((e.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointerVec,camera);if(raycaster.ray.intersectPlane(dragPlane,planeIntersect)){const targetPos=planeIntersect.clone().sub(dragOffset);const delta=targetPos.sub(activePart.g.position);activePart.userOffset.add(delta);activePart.g.position.add(delta);}updatePartLabel(e.clientX,e.clientY);return;}if(isDragging){const dx=e.clientX-startX;const dy=e.clientY-startY;yawTarget=startYaw-dx*0.0075;pitchTarget=T.MathUtils.clamp(startPitch-dy*0.005,-0.45,0.75);return;}if(e.pointerType==='mouse'){const hit=getIntersectedPart(e.clientX,e.clientY);if(hit){s.setAttribute('title',hit.part.g.name+' — Drag to move part');}else{s.setAttribute('title','Drag to rotate 360°');}}});const stopDrag=e=>{if(isDraggingPart){isDraggingPart=false;activePart=null;s.classList.remove('is-dragging-part');const pl=$('part-label');if(pl)pl.hidden=true;try{s.releasePointerCapture(e.pointerId)}catch(_){}}if(isDragging){isDragging=false;s.classList.remove('is-dragging');try{s.releasePointerCapture(e.pointerId)}catch(_){}}};s.addEventListener('pointerup',stopDrag);s.addEventListener('pointercancel',stopDrag);$('btn-reset-parts')?.addEventListener('click',e=>{e.stopPropagation();if(copier&&copier.parts){copier.parts.forEach(pt=>{if(pt.userOffset)pt.userOffset.set(0,0,0)});}});$('btn-rot-left')?.addEventListener('click',e=>{e.stopPropagation();autoSpin=false;updateAutoSpinUI();yawTarget+=Math.PI/4;});$('btn-rot-right')?.addEventListener('click',e=>{e.stopPropagation();autoSpin=false;updateAutoSpinUI();yawTarget-=Math.PI/4;});$('btn-rot-auto')?.addEventListener('click',e=>{e.stopPropagation();autoSpin=!autoSpin;updateAutoSpinUI();});$('btn-rot-reset')?.addEventListener('click',e=>{e.stopPropagation();autoSpin=false;updateAutoSpinUI();yawTarget=0;pitchTarget=0;});s.setAttribute('tabindex','0');s.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){yawTarget+=0.2;autoSpin=false;updateAutoSpinUI();}else if(e.key==='ArrowRight'){yawTarget-=0.2;autoSpin=false;updateAutoSpinUI();}else if(e.key==='ArrowUp'){pitchTarget=Math.min(pitchTarget+0.1,0.75);}else if(e.key==='ArrowDown'){pitchTarget=Math.max(pitchTarget-0.1,-0.45);}else if(e.key==='Home'||e.key==='r'){yawTarget=0;pitchTarget=0;autoSpin=false;updateAutoSpinUI();}else if(e.key==='Escape'){if(copier&&copier.parts)copier.parts.forEach(pt=>{if(pt.userOffset)pt.userOffset.set(0,0,0)});}});}
function frame(ms){requestAnimationFrame(frame);const dt=Math.min((ms-last)/1000||.016,.05);last=ms;if(document.hidden||!visible)return;p=reduced?target:T.MathUtils.lerp(p,target,1-Math.exp(-dt*9));if(Math.abs(p-target)<.00001)p=target;if(autoSpin&&!isDragging&&!isDraggingPart){yawTarget+=dt*0.45;}yaw=T.MathUtils.lerp(yaw,yawTarget,1-Math.exp(-dt*9));pitch=T.MathUtils.lerp(pitch,pitchTarget,1-Math.exp(-dt*9));poseParts(copier.parts,reduced?0:p,p*16,!reduced);const curExpl=explosionAt(reduced?0:p);if(copier&&copier.parts){for(let i=0;i<copier.parts.length;i++){const pt=copier.parts[i];if(!pt.userOffset)pt.userOffset=new T.Vector3(0,0,0);if(curExpl<0.08&&pt.userOffset.lengthSq()>0.00001){pt.userOffset.lerp(new T.Vector3(0,0,0),1-Math.exp(-dt*6));if(pt.userOffset.lengthSq()<0.0001)pt.userOffset.set(0,0,0);}pt.g.position.add(pt.userOffset);}}positionCamera();shadow.material.opacity=1-.25*curExpl;ui();renderer.render(scene,camera)}
window.addEventListener('scroll',readScroll,{passive:true});new ResizeObserver(resize).observe(stage);new IntersectionObserver(e=>{visible=e[0].isIntersecting},{rootMargin:'100px'}).observe(section);
$('motion').addEventListener('click',()=>{reduced=!reduced;motionUI()});mq.addEventListener('change',e=>{reduced=e.matches;motionUI()});
